import { tags } from "typia";

/**
 * Comprehensive platform statistics for administrator dashboard.
 *
 * Provides real-time aggregated metrics across all major platform entities including article activity, comment engagement, member statistics, section distribution, and administrative request processing. Statistics are computed at request time to ensure accuracy, with recent activity metrics covering the last 7 days.
 *
 * This response is only available to authenticated administrators due to the sensitive nature of platform-wide metrics.
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IDashboardSummary = {
  /**
   * Total count of all articles currently published on the platform.
   *
   * @x-autobe-specification Computed as COUNT(*) FROM discussion_board_articles WHERE deleted_at IS NULL. Represents total number of non-deleted articles in the system.
   */
  articles_total: number & tags.Type<"int32"> & tags.Minimum<0>;

  /**
   * Count of articles published in the last 7 days.
   *
   * @x-autobe-specification Computed as COUNT(*) FROM discussion_board_articles WHERE deleted_at IS NULL AND created_at >= NOW() - INTERVAL '7 days'. Represents articles created within the last 7 days.
   */
  articles_recent: number & tags.Type<"int32"> & tags.Minimum<0>;

  /**
   * Breakdown of article counts grouped by section, showing distribution across discussion topics.
   *
   * @x-autobe-specification Computed as SELECT section_id, COUNT(*) FROM discussion_board_articles WHERE deleted_at IS NULL GROUP BY section_id. Returns array of ISectionCount objects containing section ID and article count for each section.
   */
  articles_bySection: IDashboardSummary.ISectionCount[];

  /**
   * Total count of all comments across all articles.
   *
   * @x-autobe-specification Computed as COUNT(*) FROM discussion_board_comments WHERE deleted_at IS NULL. Represents total number of non-deleted comments across all articles.
   */
  comments_total: number & tags.Type<"int32"> & tags.Minimum<0>;

  /**
   * Average number of comments per article across the platform.
   *
   * @x-autobe-specification Computed as AVG(comment_count) from subquery: SELECT article_id, COUNT(*) as comment_count FROM discussion_board_comments WHERE deleted_at IS NULL GROUP BY article_id. If no articles exist, returns 0.
   */
  comments_averagePerArticle: number & tags.Minimum<0>;

  /**
   * Total count of all registered members on the platform.
   *
   * @x-autobe-specification Computed as COUNT(*) FROM discussion_board_members WHERE deleted_at IS NULL. Represents total number of registered members including both active and banned accounts.
   */
  members_total: number & tags.Type<"int32"> & tags.Minimum<0>;

  /**
   * Count of currently active (non-banned) members.
   *
   * @x-autobe-specification Computed as COUNT(*) FROM discussion_board_members WHERE deleted_at IS NULL AND banned = false. Represents members who can currently participate in platform activities.
   */
  members_active: number & tags.Type<"int32"> & tags.Minimum<0>;

  /**
   * Count of banned members currently restricted from platform.
   *
   * @x-autobe-specification Computed as COUNT(*) FROM discussion_board_members WHERE deleted_at IS NULL AND banned = true. Represents members who have been restricted from platform activities.
   */
  members_banned: number & tags.Type<"int32"> & tags.Minimum<0>;

  /**
   * Count of members who registered in the last 7 days.
   *
   * @x-autobe-specification Computed as COUNT(*) FROM discussion_board_members WHERE deleted_at IS NULL AND created_at >= NOW() - INTERVAL '7 days'. Tracks new user registration trends.
   */
  members_recent: number & tags.Type<"int32"> & tags.Minimum<0>;

  /**
   * Total count of discussion board sections.
   *
   * @x-autobe-specification Computed as COUNT(*) FROM discussion_board_sections. Represents total number of discussion topic categories available on the platform.
   */
  sections_total: number & tags.Type<"int32"> & tags.Minimum<0>;

  /**
   * Information about the section with the most articles, or null if no articles exist.
   *
   * @x-autobe-specification Computed by finding the section with maximum article count: SELECT s.id, s.name, COUNT(a.id) as article_count FROM discussion_board_sections s LEFT JOIN discussion_board_articles a ON s.id = a.section_id AND a.deleted_at IS NULL GROUP BY s.id, s.name ORDER BY article_count DESC LIMIT 1. Returns null if no articles exist.
   */
  sections_mostActive: IDashboardSummary.IMostActiveSection | null;

  /**
   * Count of administrator privilege requests currently pending review.
   *
   * @x-autobe-specification Computed as COUNT(*) FROM discussion_board_admin_requests WHERE deleted_at IS NULL AND status = 'pending'. Represents administrator privilege requests awaiting review by super administrators.
   */
  adminRequests_pending: number & tags.Type<"int32"> & tags.Minimum<0>;

  /**
   * Total count of administrator privilege requests that have been approved.
   *
   * @x-autobe-specification Computed as COUNT(*) FROM discussion_board_admin_requests WHERE status = 'approved'. Includes historical approved requests regardless of deletion status. Represents cumulative count of successful administrator promotions.
   */
  adminRequests_approved: number & tags.Type<"int32"> & tags.Minimum<0>;

  /**
   * Total count of administrator privilege requests that have been rejected.
   *
   * @x-autobe-specification Computed as COUNT(*) FROM discussion_board_admin_requests WHERE status = 'rejected'. Includes historical rejected requests regardless of deletion status. Represents cumulative count of denied administrator requests.
   */
  adminRequests_rejected: number & tags.Type<"int32"> & tags.Minimum<0>;
};
export namespace IDashboardSummary {
  /**
   * Information about the section with the most articles on the platform. Provides the section identifier, display name, and total article count for administrative visibility into content distribution. This object is null when no articles exist in the system.
   */
  export type IMostActiveSection = {
    /**
     * Unique identifier of the most active section.
     *
     * @x-autobe-specification Derived from discussion_board_sections.id via aggregation query. The section identifier is selected as part of the GROUP BY clause in the most active section computation: SELECT s.id FROM discussion_board_sections s ... GROUP BY s.id, s.name ORDER BY article_count DESC LIMIT 1.
     */
    id: string & tags.Format<"uuid">;

    /**
     * Display name of the most active section.
     *
     * @x-autobe-specification Derived from discussion_board_sections.name via aggregation query. The section display name is selected as part of the GROUP BY clause in the most active section computation: SELECT s.name FROM discussion_board_sections s ... GROUP BY s.id, s.name ORDER BY article_count DESC LIMIT 1.
     */
    name: string;

    /**
     * Total number of articles in this section.
     *
     * @x-autobe-specification Computed as COUNT(a.id) where a is discussion_board_articles aliased table. Only counts articles where deleted_at IS NULL. This aggregation determines which section has the most articles and drives the ORDER BY DESC LIMIT 1 selection.
     */
    article_count: number & tags.Type<"int32"> & tags.Minimum<0>;
  };

  /**
   * Represents article count statistics for a single discussion board section within the admin dashboard. Provides the section's identifying information alongside its current article count, enabling administrators to understand content distribution across discussion topics.
   */
  export type ISectionCount = {
    /**
     * Unique identifier of the discussion board section for linking to section detail views.
     *
     * @x-autobe-specification Source: discussion_board_sections.id. Computed via JOIN with discussion_board_sections table. Used as GROUP BY key and foreign key reference to the section in the aggregation query.
     */
    sectionId: string & tags.Format<"uuid">;

    /**
     * Display name of the section shown in the dashboard for administrator readability.
     *
     * @x-autobe-specification Source: discussion_board_sections.name. Computed via JOIN with discussion_board_sections table. Used in GROUP BY clause and displayed in dashboard for section identification.
     */
    name: string;

    /**
     * Number of non-deleted articles currently published in this section, showing content activity level.
     *
     * @x-autobe-specification Computed aggregation: COUNT(a.id) WHERE a.deleted_at IS NULL. Counts non-deleted articles belonging to each section via section_id foreign key. Returns 0 for sections with no articles due to LEFT JOIN behavior.
     */
    count: number & tags.Type<"int32"> & tags.Minimum<0>;
  };
}
